x['boundary_notes']=[{'printed_page':439,'side':'start','note':'438 реально просмотрена: её завершённый абзац заканчивается «وبالله التوفيق» и орнаментом.439 начинается новым разделом. Соединять абзацы438/439 не нужно.'},{'printed_page':448,'side':'end','note':'Последний абзац448 «والثاني: توحيد صحيح...» завершён словами «فإنه ملحد».449 просмотрена: начинается отдельным выводом «فهذا توحيد الطوائف، ومن الناس إلا أولئك!» и далее новым разделом. Слияние448/449 не требуется.'},{'printed_pages':[439,440],'note':'Слита фраза хадиса «أول ما تدعوهم إليه: / عبادة الله وحده»; оба source_ids сохранены.'},{'printed_pages':[440,441],'note':'Слит перенос «ويثبتون / قدمه».'},{'printed_pages':[441,442],'note':'Слит перенос «الذين يقولون إن / الله يحل بذاته».'},{'printed_pages':[442,443],'note':'Слит перенос подробного утверждения атрибутов.'},{'printed_pages':[443,444],'note':'Слит перенос перечисления видов поклонения после «ذاته وصفاته».'},{'printed_pages':[445,446],'note':'Слит перенос «وأنه / إنية كل شيء».'},{'printed_pages':[446,447],'note':'Слит перенос «ورامت / إفادته الهداية النبوية».'}]
x['review_notes']=[{'type':'source_collation','pages':list(range(439,449)),'note':'Первый фактический проход: все10 страниц439–448 прочитаны по изображениям1800px;438 и449 просмотрены только для внешних стыков. После создания перевода все10 изображений просмотрены повторно при обратной сверке. Современные сноски и маркеры исключены; авторские ссылки и полемические цитаты сохранены.'},{'type':'semantic_back_comparison','pages':list(range(439,449)),'note':'Второй фактический проход: перевод сопоставлен с повторно просмотренным арабским текстом всех10 страниц. Сохранены полная серия коранических примеров439, хадисы439–440, различение предвечности и единобожия440–441,2 группы حلول442,2 вида إفراد442–444 и все3 интерпретации определения автора444. Полностью переданы приписываемые автором учения философов, сторонников слияния, джахмитов, кадаритов и джабритов445–448 и заключительное описание позиции автора «Маназил». Они не выданы за мнение переводчика. Перечисления не сокращены.'},{'type':'russian_only_reading','pages':list(range(439,449)),'note':'Третий фактический проход: весь русский текст прочитан отдельно. Уточнено «облекаются в Его бытие»441, техническое «не привходит ни в одну из сущностей»445; реплика «Да, это запретно для вас...»447 выделена кавычками в контексте изложения критикуемой позиции. Две полные поэтические строки446/448 сохранены. Две формулы свидетельства различены от коранических цитат; все7 явных фрагментов в{}439/443 имеют тождественноеAR вRU, перевод смысла и ссылку. Проверены хеши, все source_ids и переносы.'},{'type':'print_question','pages':[439,446],'note':'В439 сохранено печатное «تنزيه الله عز وجل عن الحدث» без дополнений о الشريك из вариантов современной сноски. В446 сохранено «إنية كل شيء», переданное «само бытие каждой вещи»; это философское إنية, не آية. Поэтическое446 «تدل على أنه عينه» сохранено именно с عينه, не заменено известной строкой с واحد: это цитируемая в полемике переработка. Издательские объяснения и альтернативные чтения не импортированы.'},{'type':'uncertainty','pages':[441,444,446,447],'note':'Термины الحدث/المحدث переданы возникновение/возникшее, قيام الأفعال به — присущность Ему действий, الاتحادية — сторонники слияния; терминологическая и богословская независимая проверка остаётся необходимой. Метафора441 «تكسي وجوده: تلبسه وتخلعه» сохранена по печатным словам и передана через облачение в бытие, без исправленияAR догадкой. Текст полемический; степень точности исторических атрибуций философам/направлениям отдельно не исследована. Независимого человеческого рецензирования не было.'}]
lookup={s['id']:s['ar'] for pg in x['pages'] for s in pg['paragraphs']};used=[]
assert len(x['pages'])==10
for pg in x['pages']:
 assert pg['paragraphs']
 for i,s in enumerate(pg['paragraphs'],1):
  assert s['id']==f"v4-p{pg['printed_page']:03d}-{i:02d}"
  assert s['sha256']==hashlib.sha256(s['ar'].encode()).hexdigest()
for u in x['units']:
 assert u['ar']==' '.join(lookup[s] for s in u['source_ids'])
 assert re.findall(r'\{[^}]*\}',u['ar'])==re.findall(r'\{[^}]*\}',u['ru'])
 assert u['independent_human_review'] is False
 used+=u['source_ids']
assert len(used)==len(set(used))==len(lookup)
x['completed']=True
open(p,'w').write(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
